var e={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Gotowe do wklejenia bloki konfiguracji Klipper i makra - sekwencje startowe, obsługa filamentu, kształtowanie sygnału, siatka stołu i więcej. Skopiuj jeden i wklej go do swojego printer.cfg (Edytor konfiguracji to dobre miejsce do wklejenia).`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Pomoc`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`O szablonach konfiguracji`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Zamknij`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Jak używać`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Filtruj według kategorii, aby znaleźć makro lub blok konfiguracji.`}},{t:0,b:{t:2,i:[{t:3}],s:`Przeczytaj opis i sprawdź, jakich sekcji wymaga.`}},{t:0,b:{t:2,i:[{t:3}],s:`Skopiuj szablon, wklej go do swojej konfiguracji i dostosuj wartości.`}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:`Czym one są`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Starannie dobrany zestaw typowych elementów budulcowych Klipper: gcode_macros (PRINT_START, PAUSE/RESUME, ładowanie/rozładowanie filamentu, M600) oraz sekcje konfiguracji ([input_shaper], [bed_mesh], [firmware_retraction], …). To punkty wyjścia - przeczytaj każdy z nich i dostrój go do swojej maszyny.`}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:`Wstawianie szablonu`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Skopiuj szablon, a następnie wklej go do swojego printer.cfg - widok Raw w Edytorze konfiguracji to wygodne miejsce. Po zapisaniu restart oprogramowania go zastosuje. Zawsze najpierw sprawdź wartości; ustawienia domyślne są rozsądne, ale nie są dostrojone do Twojej drukarki.`}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:`Wymagane sekcje`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Każdy szablon wymienia sekcje konfiguracji, które definiuje lub od których zależy. Jeśli sekcja już istnieje w Twojej konfiguracji, scal klucze zamiast wklejać duplikat (zduplikowana sekcja jest odrzucana przy starcie).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Słowniczek`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:`Szablon`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Gotowy do wklejenia fragment konfiguracji Klipper lub G-code makra, który kopiujesz do printer.cfg.`}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:`gcode_macro`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Nazwane polecenie, które definiujesz w konfiguracji (np. PRINT_START) i które uruchamia sekwencję G-code.`}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:`Sekcja`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Blok konfiguracji w [nawiasach], np. [bed_mesh] - jednostka, w którą grupowana jest konfiguracja Klipper.`}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:`Kategoria`}},all:{t:0,b:{t:2,i:[{t:3}],s:`Wszystkie kategorie`}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:`Kopiuj`}},copied:{t:0,b:{t:2,i:[{t:3}],s:`Skopiowano!`}},requires:{t:0,b:{t:2,i:[{t:3,v:`Sekcje: `},{t:4,k:`sections`}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:`-`}}},count:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` szablonów`}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Wczytywanie szablonów…`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Nie udało się wczytać szablonów.`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Brak szablonów w tej kategorii.`}},retry:{t:0,b:{t:2,i:[{t:3}],s:`Ponów`}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:`Bloki konfiguracji`}},macros:{t:0,b:{t:2,i:[{t:3}],s:`Makra`}}}}};export{e as default};